UPDATE wallet
SET balance = balance + #{amount},
    total_recharge = total_recharge + #{amount},
    version = version + 1,
    update_time = #{updateTime}
WHERE member_id = #{memberId}

UPDATE wallet
SET balance = balance + #{amount},
    version = version + 1,
    update_time = #{updateTime}
WHERE member_id = #{memberId}

UPDATE wallet
SET balance = balance - #{amount},
    frozen_amount = frozen_amount + #{amount},
    version = version + 1,
    update_time = #{updateTime}
WHERE member_id = #{memberId}
  AND balance >= #{amount}

UPDATE wallet
SET frozen_amount = frozen_amount - #{amount},
    balance = balance + #{amount},
    version = version + 1,
    update_time = #{updateTime}
WHERE member_id = #{memberId}
  AND frozen_amount >= #{amount}

UPDATE wallet
SET balance = balance - #{amount},
    version = version + 1,
    update_time = #{updateTime}
WHERE member_id = #{memberId}
  AND balance >= #{amount}
